function reportPicture(at, name, left) {
  if (typeof name !== 'string' || !SHOT_NAME.test(name)) return null;
  const most = Math.min(REPORT_PICTURE_BYTES, Math.max(0, left));
  const seen = {}; const bytes = readPlainBytes(at(name), most, seen);
