  try {
    writingIn(within, cfg.projectDir, runDir, (at) => { let left = REPORT_PICTURES_BYTES; for (const { x, i } of rows) { const p = reportPicture(at, x.screenshot, left); if (p && p.data) left -= p.size; pictures[i] = p; } });
